'use client'

import { useId, useState, type ReactNode } from 'react'
import './project-grid.css'

export interface ProjectGridItem {
  id: string
  title: string
  category: string
  href: string
  description?: string
  year?: string
  /** Decorative artwork. Put information needed to understand the project in its text fields. */
  media: ReactNode
}

export interface ProjectGridProps {
  items: ProjectGridItem[]
  title?: string
  label?: string
  className?: string
  onFilterChange?: (category: string) => void
}

function decorativeMedia(element: HTMLDivElement | null) {
  element?.setAttribute('inert', '')
}

export function ProjectGrid({
  items,
  title = 'Selected work',
  label = 'Project categories',
  className = '',
  onFilterChange,
}: ProjectGridProps) {
  const headingId = useId()
  const [filter, setFilter] = useState<string | null>(null)
  const categories = [...new Set(items.map((item) => item.category))]
  const activeFilter = filter !== null && categories.includes(filter) ? filter : null
  const visibleItems = activeFilter === null ? items : items.filter((item) => item.category === activeFilter)

  function chooseCategory(category: string | null) {
    setFilter(category)
    onFilterChange?.(category ?? 'All')
  }

  return (
    <section className={`ac-project-grid ${className}`.trim()} aria-labelledby={headingId}>
      <header className="ac-project-grid-heading">
        <h2 id={headingId}>{title}</h2>
        <p className="ac-project-grid-count" role="status" aria-live="polite" aria-atomic="true">
          {visibleItems.length} {visibleItems.length === 1 ? 'project' : 'projects'}
          {activeFilter !== null && <span className="ac-project-grid-sr-only"> in {activeFilter}</span>}
        </p>
      </header>
      {items.length > 0 && (
        <div className="ac-project-grid-filters" role="group" aria-label={label}>
          <button type="button" aria-pressed={activeFilter === null} onClick={() => chooseCategory(null)}>
            All <span aria-hidden="true">{items.length.toString().padStart(2, '0')}</span>
          </button>
          {categories.map((category) => (
            <button key={category} type="button" aria-pressed={activeFilter === category} onClick={() => chooseCategory(category)}>
              {category} <span aria-hidden="true">{items.filter((item) => item.category === category).length.toString().padStart(2, '0')}</span>
            </button>
          ))}
        </div>
      )}
      {visibleItems.length > 0 ? (
        <ul className="ac-project-grid-list">
          {visibleItems.map((item) => (
            <li key={`${activeFilter ?? '*'}-${item.id}`}>
              <article className="ac-project-grid-card">
                <a href={item.href}>
                  <div ref={decorativeMedia} className="ac-project-grid-media" aria-hidden="true">{item.media}</div>
                  <div className="ac-project-grid-details">
                    <div className="ac-project-grid-meta"><span>{item.category}</span>{item.year && <span>{item.year}</span>}</div>
                    <div className="ac-project-grid-title"><h3>{item.title}</h3><span className="ac-project-grid-arrow" aria-hidden="true">↗</span></div>
                    {item.description && <p>{item.description}</p>}
                  </div>
                </a>
              </article>
            </li>
          ))}
        </ul>
      ) : <p className="ac-project-grid-empty">Projects are on the way. Check back soon.</p>}
    </section>
  )
}

.ac-project-grid{--ac-project-ink:#252820;--ac-project-muted:#72756a;--ac-project-line:#d6d7cd;--ac-project-accent:#e25434;--ac-project-radius:4px;container-type:inline-size;color:var(--ac-project-ink);font-family:inherit;width:100%;font-size:14px}
.ac-project-grid *{box-sizing:border-box}
.ac-project-grid-heading{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:22px}
.ac-project-grid-heading h2{margin:0;font-size:clamp(26px,5cqw,44px);font-weight:500;line-height:1.05;letter-spacing:-.055em}
.ac-project-grid-count{margin:0;flex-shrink:0;color:var(--ac-project-muted);font-size:11px;font-variant-numeric:tabular-nums}
.ac-project-grid-filters{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:28px}
.ac-project-grid-filters button{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:44px;border:1px solid var(--ac-project-line);border-radius:999px;padding:8px 17px;background:transparent;color:var(--ac-project-ink);font:inherit;font-size:12px;cursor:pointer;transition:background .18s,color .18s,border-color .18s}
.ac-project-grid-filters button span{font-size:9px;opacity:.65;font-variant-numeric:tabular-nums}
.ac-project-grid-filters button[aria-pressed=true]{background:var(--ac-project-ink);border-color:var(--ac-project-ink);color:var(--ac-project-selected-ink,#f7f6ef)}
.ac-project-grid-filters button:focus-visible,.ac-project-grid-card a:focus-visible{outline:2px solid var(--ac-project-accent);outline-offset:5px}
.ac-project-grid-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:32px 20px;list-style:none;margin:0;padding:0}
.ac-project-grid-list>li{min-width:0;animation:ac-project-grid-enter .35s ease-out both}
.ac-project-grid-card a{display:block;color:inherit;text-decoration:none;border-radius:var(--ac-project-radius)}
.ac-project-grid-media{overflow:hidden;isolation:isolate;aspect-ratio:4/3;border-radius:var(--ac-project-radius);background:var(--ac-project-media-background,#e6e6db);pointer-events:none}
.ac-project-grid-media>*{display:block;width:100%;height:100%;object-fit:cover;transition:transform .55s cubic-bezier(.2,.65,.3,1)}
.ac-project-grid-details{padding-top:13px}
.ac-project-grid-meta{display:flex;justify-content:space-between;gap:12px;color:var(--ac-project-muted);font-size:10px;line-height:1.4;text-transform:uppercase;letter-spacing:.065em}
.ac-project-grid-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:5px}
.ac-project-grid-title h3{margin:0;font-size:22px;font-weight:500;line-height:1.1;letter-spacing:-.04em;overflow-wrap:anywhere}
.ac-project-grid-arrow{display:grid;place-items:center;flex-shrink:0;width:28px;height:28px;border:1px solid var(--ac-project-line);border-radius:50%;font-size:17px;transition:background .2s,color .2s,border-color .2s,transform .2s}
.ac-project-grid-details p{margin:7px 0 0;max-width:36ch;color:var(--ac-project-muted);font-size:13px;line-height:1.5}
.ac-project-grid-empty{margin:0;padding:36px 0;border-top:1px solid var(--ac-project-line);color:var(--ac-project-muted);line-height:1.6}
.ac-project-grid-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(hover:hover){.ac-project-grid-card a:hover .ac-project-grid-media>*{transform:scale(1.035)}.ac-project-grid-card a:hover .ac-project-grid-arrow{background:var(--ac-project-ink);border-color:var(--ac-project-ink);color:var(--ac-project-selected-ink,#f7f6ef);transform:rotate(45deg)}.ac-project-grid-filters button:not([aria-pressed=true]):hover{border-color:var(--ac-project-ink)}}
.ac-project-grid-card a:focus-visible .ac-project-grid-arrow{background:var(--ac-project-ink);color:var(--ac-project-selected-ink,#f7f6ef)}
@container(max-width:420px){.ac-project-grid-list{grid-template-columns:minmax(0,1fr);gap:26px}.ac-project-grid-heading{margin-bottom:18px}.ac-project-grid-filters{margin-bottom:22px;gap:5px}.ac-project-grid-filters button{padding-inline:14px}.ac-project-grid-media{aspect-ratio:5/3}}
@keyframes ac-project-grid-enter{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.ac-project-grid-list>li{animation:none}.ac-project-grid-filters button,.ac-project-grid-media>*,.ac-project-grid-arrow{transition:none}}
